      "explanation": "The development of microscopy allowed scientists to observe cells. Robert Hooke used the term cell after observing compartments in cork. Later observations by Leeuwenhoek and the work of Schleiden, Schwann and Virchow helped establish the modern cell theory: organisms are composed of cells, the cell is the basic unit of life, and new cells arise from pre-existing cells.",
