      "explanation": "Mitochondria are double-membrane-bound organelles involved in aerobic cellular respiration. They release usable energy from food molecules and therefore are often called the powerhouse of the cell. Their inner membrane is folded into cristae, increasing the surface available for respiration-related reactions.",
